ListNode* somar(const ListNode* a,const ListNode* b){
    ListNode head(0);ListNode* actual=&head;int carry=0;
    while(a || b || carry){
        int soma=carry+(a?a->val:0)+(b?b->val:0);
        carry=soma/10;
        actual->next=new ListNode(soma%10);actual=actual->next;
        if(a)a=a->next;
        if(b)b=b->next;
    }
    return head.next;
}
